// Calculate technical indicators and detect divergences
function calculateRSI(prices, period = 14) {
  if (prices.length < period + 1) return 50;
  let gains = 0, losses = 0;
  const start = prices.length - period;
  for (let i = start; i < prices.length; i++) {
    const change = prices[i] - prices[i - 1];
    if (change > 0) gains += change;
    else losses -= change;
  }
  const avgGain = gains / period;
  const avgLoss = losses / period;
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return 100 - (100 / (1 + rs));
}

function calculateEMA(prices, period) {
  if (prices.length === 0) return 0;
  const multiplier = 2 / (period + 1);
  let ema = prices[0];
  for (let i = 1; i < prices.length; i++) {
    ema = (prices[i] - ema) * multiplier + ema;
  }
  return ema;
}

function calculateMACD(prices, fast = 12, slow = 26, signal = 9) {
  if (prices.length < slow) return {macd: 0, signal: 0, histogram: 0};
  const emaFast = calculateEMA(prices, fast);
  const emaSlow = calculateEMA(prices, slow);
  const macd = emaFast - emaSlow;
  return {macd, signal: macd * 0.9, histogram: macd * 0.1};
}

function extractKlines(nodeName) {
  const items = $(nodeName).all();
  if (!items || items.length === 0) return [];
  const first = items[0].json;
  // Full array as one item
  if (Array.isArray(first) && first.length && Array.isArray(first[0])) return first;
  // Split into items (each item is one candle array)
  if (Array.isArray(first) && (typeof first[0] === 'number' || typeof first[0] === 'string')) {
    return items.map(i => i.json);
  }
  // Wrapped
  if (first && Array.isArray(first.data)) return first.data;
  return items.map(i => (Array.isArray(i.json) ? i.json : null)).filter(Boolean);
}

function processKlinesData(klinesJson) {
  if (!klinesJson || !klinesJson.length) return {close: [], high: [], low: [], volume: []};
  const close = klinesJson.map(k => parseFloat(k[4]));
  const high = klinesJson.map(k => parseFloat(k[2]));
  const low = klinesJson.map(k => parseFloat(k[3]));
  const volume = klinesJson.map(k => parseFloat(k[5]));
  return {close, high, low, volume};
}

const symbols = [
  {name: 'BTC', klinesNode: 'Fetch BTC 4h Klines', fundingNode: 'Fetch BTC Funding Rate'},
  {name: 'ETH', klinesNode: 'Fetch ETH 4h Klines', fundingNode: 'Fetch ETH Funding Rate'},
];

const results = [];

for (const sym of symbols) {
  try {
    const klinesData = processKlinesData(extractKlines(sym.klinesNode));
    const fundingData = $(sym.fundingNode).first()?.json || {};
    const currentFundingRate = parseFloat(fundingData.lastFundingRate || 0);

    if (klinesData.close.length < 20) {
      results.push({
        json: {
          id: `${sym.name}_tech_${Date.now()}_short`,
          symbol: `${sym.name}USDT`,
          source: 'technical-divergence',
          overall_signal: 'NEUTRAL',
          confidence: 0.1,
          published_at: Math.floor(Date.now() / 1000),
          time_horizon: 'medium',
          topics: 'technical,divergence,insufficient-data',
          error: 'insufficient klines',
        },
      });
      continue;
    }

    const recentClose = klinesData.close.slice(-20);
    const rsi = calculateRSI(recentClose);
    const macd = calculateMACD(recentClose);
    const priceChange10 = (recentClose.slice(-1)[0] - recentClose.slice(-11)[0]) / recentClose.slice(-11)[0];

    let rsiDivergence = 'NONE';
    if (priceChange10 > 0.02 && rsi < 50) rsiDivergence = 'BEARISH';
    else if (priceChange10 < -0.02 && rsi > 50) rsiDivergence = 'BULLISH';

    let macdDivergence = 'NONE';
    if (priceChange10 > 0.015 && macd.histogram < 0) macdDivergence = 'BEARISH';
    else if (priceChange10 < -0.015 && macd.histogram > 0) macdDivergence = 'BULLISH';

    let fundingDivergence = 'NONE';
    if (currentFundingRate < -0.0005 && priceChange10 > 0.01) fundingDivergence = 'BULLISH';
    else if (currentFundingRate > 0.0005 && priceChange10 < -0.01) fundingDivergence = 'BEARISH';

    const signals = [];
    if (rsiDivergence !== 'NONE') signals.push(rsiDivergence);
    if (macdDivergence !== 'NONE') signals.push(macdDivergence);
    if (fundingDivergence !== 'NONE') signals.push(fundingDivergence);

    let overallSignal = 'NEUTRAL';
    let confidence = 0.3;
    const bullishCount = signals.filter(s => s === 'BULLISH').length;
    const bearishCount = signals.filter(s => s === 'BEARISH').length;
    if (bullishCount >= 2) { overallSignal = 'BULLISH'; confidence = 0.6 + (bullishCount * 0.1); }
    else if (bearishCount >= 2) { overallSignal = 'BEARISH'; confidence = 0.6 + (bearishCount * 0.1); }

    results.push({
      json: {
        id: `${sym.name}_tech_${Date.now()}`,
        symbol: `${sym.name}USDT`,
        source: 'technical-divergence',
        rsi: Number(rsi.toFixed(2)),
        macd_histogram: Number(macd.histogram.toFixed(6)),
        price_change_4h: Number((priceChange10 * 100).toFixed(4)),
        funding_rate: Number((currentFundingRate * 10000).toFixed(4)),
        rsi_divergence: rsiDivergence,
        macd_divergence: macdDivergence,
        funding_divergence: fundingDivergence,
        overall_signal: overallSignal,
        confidence: Number(Math.min(confidence, 0.95).toFixed(4)),
        published_at: Math.floor(Date.now() / 1000),
        time_horizon: 'medium',
        topics: 'technical,divergence,rsi,macd,funding',
      },
    });
  } catch (e) {
    results.push({
      json: {
        id: `${sym.name}_tech_${Date.now()}_error`,
        symbol: `${sym.name}USDT`,
        source: 'technical-divergence',
        rsi: 50,
        macd_histogram: 0,
        price_change_4h: 0,
        funding_rate: 0,
        rsi_divergence: 'NONE',
        macd_divergence: 'NONE',
        funding_divergence: 'NONE',
        overall_signal: 'NEUTRAL',
        confidence: 0.1,
        published_at: Math.floor(Date.now() / 1000),
        time_horizon: 'medium',
        topics: 'technical,divergence,error',
        error: String(e.message || e),
      },
    });
  }
}

return results;
